import {createDemoState,createEmptyState,recordEvent,getActiveEvents,getDaySummary,getStock,getHistory} from './pilot-model.mjs';
const TODAY='2026-10-18', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>v===null||v===undefined?'—':new Intl.NumberFormat('es-CO',{maximumFractionDigits:1}).format(v);
const labels={collection:'Recogida',classification:'Clasificación',supply:'Suministro',mortality:'Mortalidad',feed_receipt:'Entrada de alimento',close:'Cierre de prueba'};
const cats=['YUMBO','EXTRA','AA','A','B','C','ROTOS','BLANCO','PIPO'];
let mode='demo',view='overview',date=TODAY,month=TODAY.slice(0,7),states={},editing=null;
function warning(message){$('#storageWarning').hidden=false;$('#storageWarning').textContent=message;}
for(const m of ['demo','field']){try{const raw=localStorage.getItem('tamago:pilot:v1:'+m);if(raw){const s=JSON.parse(raw);if(s.schemaVersion!==1||!Array.isArray(s.lots)||!Array.isArray(s.events))throw Error();getHistory(s,s.selectedLotId);states[m]=s;}}catch{warning('No se pudo leer un guardado local. No será reemplazado automáticamente; exporta o revisa el almacenamiento antes de registrar.');}}
states.demo??=createDemoState(TODAY);
const state=()=>states[mode],lot=()=>state()?.lots.find(l=>l.id===state().selectedLotId);
function save(s){if(!$('#storageWarning').hidden)throw Error('El guardado está bloqueado por un problema de almacenamiento.');try{localStorage.setItem('tamago:pilot:v1:'+mode,JSON.stringify(s));}catch{throw Error('No se pudo guardar. No cierres esta ventana; revisa el espacio del navegador.');}states[mode]=s;}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4000);}
function button(text,action,extra=''){return `<button class="button button-secondary" data-action="${action}" ${extra}>${text}</button>`;}
function metric(label,value,foot='',accent=false){return `<article class="kpi-card ${accent?'accent':''}"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></article>`;}
function heading(title,description){return `<div class="page-heading"><div><div class="eyebrow">OPERACIÓN · ${esc(lot()?.code||'TU NUEVO LOTE')}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-controls"><label><span>Fecha de trabajo</span><input id="workDate" type="date" value="${date}" min="${lot()?.startDate||''}"></label>${button('Registrar +','choose')}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">Sin registros en este período.</td></tr>`}</tbody></table></div>`;}
function eventButton(type,id,text){return button(text||labels[type],type,id?`data-edit="${esc(id)}"`:'');}
function render(){
 $('#workspaceMode').value=mode;$('#lotLabel').textContent=lot()?.code||'Sin configurar';$('#environmentText').textContent=mode==='demo'?'Ejemplo ficticio · no son datos de tu empresa. Guardado en este navegador.':'Mi prueba nueva · datos locales, sin envío ni sincronización.';
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 if(!state()&&view!=='setup'){$('#screen').innerHTML=`<section class="empty-state"><div class="eyebrow">UNA NUEVA ETAPA</div><h2>Comencemos con un lote nuevo.</h2><p>La prueba de campo no depende de resolver el histórico AH2. Configura el punto de partida y registra las operaciones desde su origen.</p>${button('Preparar mi prueba','setup')}</section>`;return;}
 if(view==='setup'){renderSetup();return;}
 if(date<lot().startDate)date=lot().startDate;
 const d=getDaySummary(state(),lot().id,date),stock=getStock(state(),lot().id,date),history=getHistory(state(),lot().id),rows=history.filter(r=>r.date.startsWith(month));
 $('#pendingBadge').textContent=String((3-d.collections.length)+!d.classEventId+!d.supplyEventId+!d.mortalityEventId+(d.classEventId&&d.difference!==0?1:0));
 let html='';
 if(view==='overview'){
 html=heading('Lo que pasa en tu lote.','Una mirada a la operación, con cifras que nacen de cada registro.');
 html+=`<div class="section-kicker">PANORAMA DEL DÍA <span></span><span class="pill ${d.closed?'pill-green':'pill-amber'}">${d.closed?'Jornada cerrada':'Jornada en curso'}</span></div><div class="kpi-grid">${metric('Huevos recogidos',n(d.collected),`${d.collections.length} de 3 recogidas registradas`,true)}${metric('Clasificados para venta',n(d.classifiedForSale),d.classEventId?'Informe registrado':'Falta el informe')}${metric('Pendientes de clasificar',n(d.unclassified),'Balance de la fecha seleccionada')}${metric('Alimento suministrado',n(d.feedSuppliedKg)+' kg',d.supplyEventId?'Suministro informado · no ingesta medida':'Sin informar todavía')}</div>`;
 const chart=history.filter(r=>r.date<=date).slice(-7),max=Math.max(1,...chart.map(r=>r.collected));
 html+=`<div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><h2>El ritmo de la producción</h2><p>Últimas jornadas con registros · huevos recogidos</p></div><span class="pill pill-neutral">${mode==='demo'?'Datos ficticios':'Datos locales'}</span></div><div style="height:210px;display:flex;gap:16px;align-items:end;padding:20px">${chart.map(r=>`<div style="flex:1;text-align:center;font-size:11px;color:#758078"><div>${n(r.collected)}</div><div style="height:${Math.max(2,r.collected/max*145)}px;background:${r.date===date?'#173d32':'#d9e5c8'};border-radius:7px 7px 0 0;margin-top:8px"></div><div style="margin-top:8px">${r.date.slice(8)}/${r.date.slice(5,7)}</div></div>`).join('')||'Aún no hay jornadas registradas.'}</div><p class="subtle-note">Solo se muestran días informados. Ausencia de dato no significa producción cero.</p></section><section class="panel today-panel"><div class="panel-heading"><div><h2>Tu siguiente paso</h2><p>Completa el día en el lugar donde sucede.</p></div></div>${[['collection',d.collections.length===3,'Las tres recogidas'],['classification',!!d.classEventId,'Clasificación de bodega'],['supply',!!d.supplyEventId,'Alimento suministrado'],['mortality',!!d.mortalityEventId,'Mortalidad, incluso cero']].map(([t,ok,title])=>`<div class="task-item ${ok?'':'pending'}"><span class="task-symbol">${ok?'✓':'○'}</span><div><strong>${title}</strong><small>${ok?'Informado':'Pendiente de registrar'}</small></div></div>`).join('')}${button('Ir a mi jornada →','day')}</section></div>`;
 html+=`<div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Lectura operativa</h2><p>Cálculos observados, no diagnóstico biológico</p></div></div><div class="mini-metrics"><div class="mini-metric"><span>Postura observada</span><strong>${n(d.posturePct)} %</strong></div><div class="mini-metric"><span>Suministro por ave</span><strong>${n(d.gramsPerBird)} g</strong></div><div class="mini-metric"><span>Aves según registros</span><strong>${n(d.birds)}</strong></div></div><p class="subtle-note">Postura = recogidos ÷ aves al cierre × 100. Suministro = bultos × 40 kg. Un día incompleto produce indicadores parciales.</p></section><section class="panel"><div class="panel-heading"><div><h2>Prueba por etapas</h2><p>Primero, capturar bien. Después, conectar.</p></div></div><p>Este boceto valida registro, balances y correcciones. Facturación, despachos, costos multiempresa y comparación causal de alimentos siguen fuera de esta etapa.</p>${button('Ver alcance y preparación','setup')}</section></div>`;
 }else if(view==='day'){
 html=heading('Cada jornada, bien registrada.','Tres recogidas, un informe de clasificación y los datos del galpón.');
 html+=`<div class="collection-grid">${[1,2,3].map(turn=>{const c=d.collections.find(c=>c.turn===turn);return `<article class="collection-card ${c?'':'pending'}"><small>RECOGIDA ${turn}</small><strong class="big-quantity">${c?n(c.quantity):'Por informar'}</strong><span class="pill ${c?'pill-green':'pill-amber'}">${c?'Registrada':'Pendiente'}</span>${d.closed?'':button(c?'Corregir':'Registrar','collection',`data-turn="${turn}" ${c?`data-edit="${c.id}"`:''}`)}</article>`;}).join('')}</div><div class="day-grid section-space"><section class="panel"><div class="panel-heading"><div><h2>Balance de clasificación</h2><p>La misma fecha de recogida, sin duplicar los sucios.</p></div>${d.closed?'':eventButton('classification',d.classEventId,d.classEventId?'Corregir informe':'Registrar informe')}</div><div class="balance-row"><div class="balance-number"><small>Recogidos</small><strong>${n(d.collected)}</strong></div><b>−</b><div class="balance-number"><small>Procesados</small><strong>${n(d.processed)}</strong></div><b>=</b><div class="balance-number"><small>Pendientes</small><strong>${n(d.difference)}</strong></div></div>${table(['Resultado','Huevos'],[...cats.map(c=>`<tr><td>${c}</td><td>${n(d.quantities[c])}</td></tr>`),`<tr><td>Sucios pendientes de tratamiento</td><td>${n(d.dirty)}</td></tr>`,`<tr><td>Descartes</td><td>${n(d.lost)}</td></tr>`])}<p class="subtle-note">Procesados = tipologías + sucios pendientes + descartes. Tratar sucios requiere corregir este mismo informe, sin volver a sumarlos. Yemas y represamientos entre fechas quedan fuera del primer boceto.</p></section><aside><section class="panel"><div class="panel-heading"><h2>Parte del galpón</h2></div><p>Suministro: <strong>${n(d.feedSuppliedBags)} bultos</strong></p>${d.closed?'':eventButton('supply',d.supplyEventId,d.supplyEventId?'Corregir suministro':'Informar suministro')}<p>Mortalidad: <strong>${n(d.mortality)} aves</strong></p>${d.closed?'':eventButton('mortality',d.mortalityEventId,d.mortalityEventId?'Corregir mortalidad':'Informar mortalidad')}</section><section class="panel section-space close-panel"><h2>${d.closed?'Jornada cerrada':'Revisar antes de cerrar'}</h2><p>${d.closed?'Revisor declarado: '+esc(d.closedBy):'Se requieren tres recogidas, clasificación sin diferencia, suministro y mortalidad explícitos.'}</p>${d.closed?'':eventButton('close',null,'Revisar cierre')}<p class="subtle-note">Cierre local de prueba, sin firma ni autenticación. La reapertura aún no está implementada.</p></section></aside></div>`;
 }else if(view==='feed'){
 html=heading('Alimento con trazabilidad.','Separa la llegada física del suministro diario. No son la misma operación.');
 html+=`<div class="kpi-grid">${metric('Saldo informado',n(stock.feedBags)+' bultos','Al corte de la fecha seleccionada',true)}${metric('Equivalencia',n(stock.feedBags*40)+' kg','Bultos de 40 kg')}${metric('Suministro del día',n(d.feedSuppliedBags),'No equivale a consumo biológico')}${metric('Suministro por ave',n(d.gramsPerBird)+' g','Usa aves al cierre registradas')}</div><section class="panel"><div class="panel-heading"><div><h2>Movimientos de alimento</h2><p>Saldo inicial + entradas − suministros.</p></div>${eventButton('feed_receipt',null,'Registrar llegada')}</div>${table(['Fecha','Movimiento','Bultos','Fórmula recibida'],getActiveEvents(state()).filter(e=>['feed_receipt','supply'].includes(e.type)&&e.businessDate<=date).sort((a,b)=>b.businessDate.localeCompare(a.businessDate)).map(e=>`<tr><td>${e.businessDate}</td><td>${labels[e.type]}</td><td>${e.type==='supply'?'−':'+'}${n(e.payload.bags)}</td><td>${esc(e.payload.formula||'—')}</td></tr>`))}<p class="subtle-note">El saldo inicial es ${n(lot().openingFeedBags)} bultos. Este boceto no asigna automáticamente qué fórmula fue realmente suministrada ni implementa FIFO, préstamos o costos.</p></section>`;
 }else if(view==='stock'){
 html=heading('Existencias, sin adivinarlas.','Acumulado desde el inicio configurado hasta la fecha de trabajo.');
 html+=`<div class="callout warning"><div><strong>Acumulado de producción, no inventario comercial conciliado.</strong><p>Aún no se descuentan despachos, ventas ni consumo interno. No usar estas cifras para prometer disponibilidad a clientes.</p></div></div><div class="kpi-grid section-space">${metric('Clasificados acumulados',n(stock.eggsTotal),'Sin salidas registradas',true)}${metric('Sucios pendientes',n(stock.dirty),'Requieren tratamiento')}${metric('Sin clasificar',n(stock.unclassified),'Pendiente acumulado')}${metric('Alimento',n(stock.feedBags)+' bultos','Saldo físico modelado')}</div><section class="panel">${table(['Tipología','Huevos acumulados'],cats.map(c=>`<tr><td>${c}</td><td>${n(stock.eggs[c])}</td></tr>`))}</section>`;
 }else{
 html=heading('Un dato. Su historia.','Consulta jornadas y conserva el rastro de las correcciones.');
 html+=`<section class="panel"><div class="panel-heading"><div><h2>Jornadas del mes</h2><p>${rows.length} días con información · ${rows.filter(r=>r.closed).length} cerrados</p></div><label>Mes <input id="monthFilter" type="month" value="${month}"></label></div>${table(['Fecha','Recogidos','Clasificados','Suministro kg','Estado'],rows.map(r=>`<tr><td><button class="button button-plain" data-action="open-date" data-date="${r.date}">${r.date}</button></td><td>${n(r.collected)}</td><td>${n(r.classifiedForSale)}</td><td>${n(r.feedSuppliedKg)}</td><td>${r.closed?'Cerrada':'En curso'}</td></tr>`))}</section><section class="panel section-space"><div class="panel-heading"><div><h2>Rastro de registros</h2><p>Se conserva el original al corregir. Hora de captura diferente a fecha operativa.</p></div></div>${table(['Fecha efectiva','Evento','Captura','Corrección'],state().events.filter(e=>e.businessDate.startsWith(month)).slice().reverse().map(e=>`<tr><td>${e.businessDate}</td><td>${labels[e.type]}</td><td>${esc(new Date(e.recordedAt).toLocaleString('es-CO'))}</td><td>${esc(e.reason||'Registro original')}</td></tr>`))}</section>`;
 }
 $('#screen').innerHTML=html;
}
function field(name,label,type='text',value='',extra=''){return `<label class="form-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;}
function renderSetup(){const configured=!!states.field;$('#screen').innerHTML=`<div class="page-heading"><div><div class="eyebrow">PRUEBA DE CAMPO · ETAPA 1</div><h1>Empezar desde el origen.</h1><p>Un lote nuevo y un mes de trabajo actual. El histórico no bloquea esta prueba.</p></div></div><div class="setup-layout"><section class="panel"><h2>${configured?'Tu prueba ya está preparada':'Configura el punto de partida'}</h2>${configured?`<p>Lote <strong>${esc(states.field.lots[0].code)}</strong> · ${esc(states.field.lots[0].site)}</p><p>Para preservar los registros, este boceto no permite reemplazar el lote configurado.</p>${button('Entrar a mi prueba','field')}`:`<form id="setupForm"><div class="form-grid">${field('code','Código del nuevo lote','text','','maxlength="32" placeholder="Ej. AH4"')}${field('name','Nombre descriptivo')}${field('site','Granja / sede')}${field('initialBirds','Aves al inicio de la prueba','number','','min="1" step="1"')}${field('startDate','Fecha inicial de la prueba','date',TODAY)}${field('openingFeedBags','Alimento existente al inicio · bultos 40 kg','number',0,'min="0" step="0.01"')}${field('formula','Fórmula inicial identificada','text','Sin identificar')}</div><p class="subtle-note">Esta fecha marca el corte del piloto, no necesariamente el nacimiento o llegada de las aves. Aves y alimento deben verificarse físicamente.</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="button button-primary">Crear mi prueba local</button></div></form>`}</section><aside class="setup-aside"><h2>Qué vamos a validar</h2><ul class="setup-points"><li>El galponero registra las recogidas, suministro y mortalidad.</li><li>Bodega informa tipologías, sucios y descartes.</li><li>Un responsable revisa diferencias y cierra.</li><li>Elkin recibe reglas y estados verificables, no solo pantallas.</li></ul><p class="subtle-note">Hoy todos operan en un solo navegador. Roles, cuentas, respaldo remoto y sincronización son requisitos de la siguiente implementación, no funciones existentes.</p><a href="./vision.html">Explorar la visión multiempresa →</a></aside></div>`;}
function openDialog(type,id=null,turn=1){
 if(!state()){view='setup';render();return;}editing={type,id};const e=state().events.find(e=>e.id===id),p=e?.payload||{};
 let body='';
 if(type==='choose'){body=`<div class="event-choices">${Object.entries(labels).filter(([t])=>t!=='close').map(([t,l])=>`<button class="event-choice" data-action="${t}"><div><strong>${l}</strong><small>Registrar en la fecha seleccionada</small></div><span>→</span></button>`).join('')}</div>`;}
 else if(type==='collection')body=field('turn','Número de recogida','number',p.turn||turn,'min="1" max="3" step="1"')+field('quantity','Huevos recogidos · unidades','number',p.quantity??'','min="0" step="1"');
 else if(type==='classification')body=`<div class="class-fields">${cats.map(c=>field(c,c,'number',p.quantities?.[c]??0,'min="0" step="1"')).join('')}${field('dirty','Sucios pendientes','number',p.dirty??0,'min="0" step="1"')}${field('lost','Descartes','number',p.lost??0,'min="0" step="1"')}</div><p class="subtle-note">Unidades de huevo. Yemas y clasificación de recogidas de otras fechas no están soportadas en esta etapa.</p><label><input type="checkbox" required> Revisé las cantidades; los ceros son explícitos.</label>`;
 else if(type==='supply'||type==='feed_receipt')body=field('bags','Bultos de 40 kg','number',p.bags??'','min="0" step="0.01"')+(type==='feed_receipt'?field('formula','Proveedor / fórmula recibida','text',p.formula||''):'<p class="subtle-note">Suministro informado por el galponero, no alimento comprado ni ingesta medida.</p>');
 else if(type==='mortality')body=field('quantity','Aves muertas · escribir 0 si no hubo','number',p.quantity??'','min="0" step="1"');
 else body=`<p>Se verificará que no falten informes ni haya diferencia de clasificación. Tras cerrar, no se podrá corregir esta jornada en el boceto.</p>${field('closedBy','Nombre de quien revisa')}<p class="subtle-note">Nombre declarado, no identidad autenticada ni firma digital.</p>`;
 $('#dialogContent').innerHTML=`<div class="dialog-head"><div><h2 id="dialogTitle">${type==='choose'?'¿Qué vas a registrar?':(id?'Corregir: ':'')+labels[type]}</h2><p>${esc(lot().code)} · ${date}</p></div><button class="close-icon" data-action="dismiss" aria-label="Cerrar">×</button></div>${type==='choose'?`<div class="dialog-body">${body}</div>`:`<form id="eventForm"><div class="dialog-body">${body}${id?field('reason','Motivo de la corrección'):''}<p class="form-error" role="alert"></p></div><div class="dialog-actions">${button('Cancelar','dismiss')}<button class="button button-primary">${type==='close'?'Cerrar jornada de prueba':'Guardar en este navegador'}</button></div></form>`}`;
 if(!$('#recordDialog').open)$('#recordDialog').showModal();
}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action],[data-view]');if(!b)return;const a=b.dataset.action;if(b.dataset.view){view=b.dataset.view;render();return;}if(a==='dismiss'){$('#recordDialog').close();return;}if(a==='setup'){view='setup';render();return;}if(a==='field'){mode='field';view='overview';render();return;}if(a==='day'){view='day';render();return;}if(a==='open-date'){date=b.dataset.date;view='day';render();return;}if(a==='export'){if(!state()){toast('Primero configura tu prueba.');return;}const url=URL.createObjectURL(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),localOnly:true,state:state()},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`tamago-${mode}-${date}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(a==='choose'||labels[a])openDialog(a,b.dataset.edit,Number(b.dataset.turn||1));});
document.addEventListener('change',ev=>{if(ev.target.id==='workspaceMode'){mode=ev.target.value;view='overview';render();}if(ev.target.id==='workDate'&&ev.target.value){date=ev.target.value;render();}if(ev.target.id==='monthFilter'){month=ev.target.value;render();}});
document.addEventListener('submit',ev=>{if(!['eventForm','setupForm'].includes(ev.target.id))return;ev.preventDefault();const f=ev.target,values=new FormData(f),num=k=>{const v=values.get(k);if(v===null||String(v).trim()==='')throw Error('Completa todas las cantidades; escribe cero cuando corresponda.');return Number(v);};try{if(f.id==='setupForm'){const s=createEmptyState({code:values.get('code'),name:values.get('name'),site:values.get('site'),initialBirds:num('initialBirds'),startDate:values.get('startDate'),formula:values.get('formula'),openingFeedBags:num('openingFeedBags')});mode='field';save(s);date=s.lots[0].startDate;month=date.slice(0,7);view='day';}else{const {type,id}=editing;let payload;if(type==='collection')payload={turn:num('turn'),quantity:num('quantity')};else if(type==='classification')payload={quantities:Object.fromEntries(cats.map(c=>[c,num(c)])),dirty:num('dirty'),lost:num('lost')};else if(type==='supply')payload={bags:num('bags')};else if(type==='feed_receipt')payload={bags:num('bags'),formula:values.get('formula')};else if(type==='mortality')payload={quantity:num('quantity')};else payload={closedBy:values.get('closedBy')};save(recordEvent(state(),{type,lotId:lot().id,businessDate:date,payload,...(id?{supersedes:id,reason:values.get('reason')}:{})}));$('#recordDialog').close();}render();toast('Guardado en este navegador.');}catch(error){f.querySelector('.form-error').textContent=error.message;}});
// Small code-native icons; no external assets or network requests.
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 12h8M12 8v8"/></svg>';});
render();
